    Invokes the system 'find' command to search for a pattern in the current directory.
    """
    try:
        result = subprocess.check_output(['find', '.', '-name', pattern], text=True)
        return result.splitlines()
    except subprocess.CalledProcessError as e:
        print(f"Error executing find: {e}")
        return []
