def list_directory_contents(target_directory):
    """
    Safely list the contents of a directory using os.listdir 
    to avoid shell injection vulnerabilities associated with os.system.
    """
    if os.path.isdir(target_directory):
        return os.listdir(target_directory)
    else:
        raise ValueError("Invalid directory path.")
