import subprocess
import csv

def extract_pdf_metadata_to_csv(pdf_filename, csv_filename):
    """
    Invokes pdfinfo to extract metadata from a PDF and saves it to a CSV file.
    """
    result = subprocess.run(['pdfinfo', pdf_filename], capture_output=True, text=True)

    if result.returncode == 0:
        metadata = {}
        for line in result.stdout.splitlines():
            if ':' in line:
                key, value = line.split(':', 1)
                metadata[key.strip()] = value.strip()

        with open(csv_filename, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['Key', 'Value'])
            for key, value in metadata.items():
                writer.writerow([key, value])
    else:
        print(f"Error: {result.stderr}")
```

