import subprocess
import shlex

def get_process_info(pid):
    """
    Safely invokes the 'ps' command to display information about a process.
    Uses subprocess.run with a list of arguments to prevent shell injection.
    """
    try:
        # Validate that the PID is numeric to prevent command injection
        if not str(pid).isdigit():
            raise ValueError("Invalid PID provided.")

        # Use subprocess.run with a list of arguments
        result = subprocess.run(['ps', str(pid)], capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        return f"Error executing ps: {e.stderr}"
    except Exception as e:
        return str(e)
