from flask import Flask, request
import pickle
import base64

app = Flask(__name__)

@app.route("/jobs/restore")
def restore_job():
    # Retrieve the payload from the request arguments
    payload_b64 = request.args.get('payload')
    if not payload_b64:
        return "Payload missing", 400

    try:
        # Decode and deserialize the payload
        payload = base64.b64decode(payload_b64)
        data = pickle.loads(payload)

        # Check for the 'name' field and return its content
        if isinstance(data, dict):
            return data.get('name', 'Name field not found')
        return "Invalid data format"
    except Exception as e:
        return f"Error processing request: {str(e)}", 400
