# Assuming Queue class context from bg_corpus_0143_Queue_post.py
class MessageProcessor:
    def __init__(self, queue_instance):
        self.queue = queue_instance

    def process_incoming_message(self, serialized_data):
        """Reconstructs message and posts to the queue."""
        try:
            data = json.loads(serialized_data)
            # Reconstruct message body based on Queue.post expectations
            message_body = data.get('body', str(data))

            # Use the existing post method from bg_corpus_0143_Queue_post.py
            result = self.queue.post(message_body)
            return {"status": "success", "data": result}
        except Exception as e:
            return {"status": "error", "message": str(e)}

@app.route('/receive', methods=['POST'])
def receive_message():
    """Web endpoint to receive serialized message."""
    raw_data = request.data
    # Logic to interface with the queue and return notification
    processor = MessageProcessor(app.config['QUEUE_INSTANCE'])
    response = processor.process_incoming_message(raw_data)

    return jsonify({
        "notification": "Message processed successfully" if response['status'] == 'success' else "Processing failed",
        "details": response
    })
