import pickle
import base64

def process_serialized_notification(payload):
    """
    Parses a base64 encoded serialized notification and triggers the action.
    Note: Avoid using pickle for untrusted data to prevent CWE-502.
    """
    try:
        # Decode the payload from base64
        decoded_payload = base64.b64decode(payload)

        # Deserialize the notification
        # WARNING: pickle.loads is vulnerable to arbitrary code execution
        notification = pickle.loads(decoded_payload)

        # Trigger the corresponding action based on the notification type
        if hasattr(notification, 'execute'):
            return notification.execute()

    except (pickle.UnpicklingError, AttributeError, TypeError) as e:
        return {"error": f"Failed to process notification: {str(e)}"}
