import os
import requests

def authenticate_and_validate(client_id, client_secret, authorization_code):
    """
    Authenticates with an identity provider using client credentials 
    and exchanges an authorization code to validate user identity.
    """
    token_url = "https://identity-provider.com/oauth/token"
    user_info_url = "https://identity-provider.com/oauth/userinfo"

    # Exchange code for access token
    token_response = requests.post(token_url, data={
        'grant_type': 'authorization_code',
        'client_id': client_id,
        'client_secret': client_secret,
        'code': authorization_code
    })

    if token_response.status_code != 200:
        raise requests.HTTPError("Failed to obtain access token")

    access_token = token_response.json().get('access_token')

    # Validate user identity
    user_response = requests.get(user_info_url, headers={
        'Authorization': f'Bearer {access_token}'
    })

    if user_response.status_code == 200:
        return user_response.json()
    else:
        raise requests.HTTPError("Failed to validate user identity")
