from flask import abort

def validate_user_access(service, auth_token):
    """
    Authenticates with the authorization service using a secret from environment variables
    and validates the provided user access token.
    """
    # Retrieve the secret from environment variables to avoid hardcoding (CWE-798)
    service_secret = os.environ.get('SERVICE_SECRET')

    if not service_secret:
        raise EnvironmentError("SERVICE_SECRET environment variable not set.")

    if not service or not auth_token:
        abort(400, "Missing service or auth_token parameter.")

    headers = {
        "Authorization": f"Bearer {auth_token}",
        "X-Service-Secret": service_secret
    }

    try:
        response = requests.get(f"https://authorization_service/{service}", headers=headers)
        if response.status_code != 200:
            abort(401, "Authentication failed.")
        return response.json()
    except requests.exceptions.RequestException:
        abort(500, "Authorization service unreachable.")
