from flask import request, Response
import csv
import io

@app.route('/serve-csv', methods=['GET'])
def serve_csv():
    filename = request.args.get('filename', 'data.csv')
    delimiter = request.args.get('delimiter', ',')

    # Example: Reading from a file as seen in bg_corpus_0364_IOSXR_load_candidate_config.py
    # and processing with csv module
    def generate():
        with open(filename, 'r') as f:
            reader = csv.reader(f, delimiter=delimiter)
            for row in reader:
                yield ','.join(row) + '\n'

    return Response(
        generate(),
        mimetype='text/csv',
        headers={'Content-Disposition': 'attachment; filename="%s"' % filename}
    )
