import requests

class FeatureFlagService:
    def __init__(self, config_url):
        self.config_url = config_url
        self.snapshot = None

    def fetch_snapshot(self):
        """Retrieves and reconstructs the feature-flag snapshot."""
        response = requests.get(self.config_url)
        if response.ok:
            # Reconstruct the snapshot object from serialized JSON
            self.snapshot = response.json()
        else:
            self.snapshot = {}

    def is_enabled(self, feature_name):
        """Determines whether a requested feature is enabled."""
        if not self.snapshot:
            self.fetch_snapshot()

        # Access the feature flag status from the reconstructed object
        features = self.snapshot.get('features', {})
        return features.get(feature_name, {}).get('enabled', False)
