import requests

class FeatureFlagService:
    def __init__(self, config_url):
        self.config_url = config_url
        self.snapshot = None

    def fetch_snapshot(self):
        """Retrieves and reconstructs the feature-flag snapshot."""
        response = requests.get(self.config_url)
        if response.ok:
            # Reconstruct the snapshot object from the serialized JSON
            self.snapshot = response.json()
        else:
            self.snapshot = None
            raise Exception(f"Failed to fetch snapshot: {response.status_code}")

    def is_enabled(self, feature_name):
        """Determines whether a requested feature is enabled."""
        if not self.snapshot or 'features' not in self.snapshot:
            return False

        # Access the feature status within the reconstructed object
        feature = self.snapshot['features'].get(feature_name)
        return feature.get('enabled', False) if feature else False
